// Well Test video round (2026-10-14): a buildup after a rate history.
// The studio reads a clean-up test (three rates with a shut-in, then the
// buildup) generated by the engine's own superposition model, and recovers
// the generating k and skin only when the time basis is the rate history.
// Also: the late (second) semilog line gives the fault distance of a
// sealing-fault test, the MDH cross-check, and the honest time-basis text.
import { mountStudio } from './reportTestKit';
import { buildRateHistorySpec } from '@/contexts/WellTestStudioContext';
import { timeBasisText } from '@/utils/welltest/reportModel';
import { getModel, evaluateBuildupFromHistory, evaluateBuildup } from '@/utils/welltest/models/modelCatalog';
import { rateStepsFromHistory } from '@/utils/welltest/superposition';

const RES = { h: '21', phi: '0.2', rw: '0.51', B: '1.21', mu: '1.8', ct: '0.0000127', q: '140', pi: '2120' };
const resNum = Object.fromEntries(Object.entries(RES).map(([k, v]) => [k, Number(v)]));
const TRUTH = { k: 225, skin: 3.2, C: 0.0004 };
const RATES = [{ t: '0', q: '60' }, { t: '6', q: '0' }, { t: '7', q: '100' }, { t: '15', q: '140' }, { t: '27', q: '0' }];
const logspace = (a, b, n) => Array.from({ length: n }, (_, i) => 10 ** (a + ((b - a) * i) / (n - 1)));

const cleanupGauge = () => {
  const steps = rateStepsFromHistory(RATES.map((r) => ({ t: Number(r.t), q: Number(r.q) })));
  const dts = logspace(-2, Math.log10(48), 60);
  const bu = evaluateBuildupFromHistory({ model: getModel('homogeneous'), params: TRUTH, reservoir: resNum, steps, shutInTime: 27, dts });
  return { rows: bu.map((p) => ({ t: p.dt, p: p.pws })), pwf: bu.pwfAtShutIn };
};

async function setup(basis) {
  const studio = mountStudio();
  const g = cleanupGauge();
  await studio.act((c) => {
    Object.entries(RES).forEach(([k, v]) => c.setReservoirField(k, v));
    c.setTestField('testType', 'buildup');
    c.setTestField('tp', '24');
    c.setTestField('pwfShutIn', String(g.pwf));
    c.setTestField('pointsPerDecade', '30');
    c.setTestField('timeBasis', basis);
    c.setRateRows(RATES);
    c.setGaugeRows(g.rows);
    c.setWindowField('semilogMin', '5');
    c.setWindowField('semilogMax', '48');
  });
  return studio;
}

describe('the rate history spec', () => {
  test('the analysed shut-in is the last one, after the clean-up shut-in', () => {
    const h = buildRateHistorySpec(RATES);
    expect(h.ok).toBe(true);
    expect(h.shutInTime).toBe(27);
    expect(h.qn).toBe(140);
    expect(h.steps).toHaveLength(4);
    expect(h.equivalentTp).toBeCloseTo((60 * 6 + 100 * 8 + 140 * 12) / 140, 9);
    expect(buildRateHistorySpec([{ t: '0', q: '100' }]).ok).toBe(false);
  });

  test('the report states the basis it used', () => {
    expect(timeBasisText({ family: 'buildup' }, null)).toMatch(/used only when the time basis is set to the rate history/);
    expect(timeBasisText({ family: 'buildup' }, buildRateHistorySpec(RATES))).toMatch(/superposition of its 4 rate steps before the shut-in at 27 hr/);
  });
});

describe('a buildup after a clean-up', () => {
  test('on the rate history the line recovers k, skin and p* = pi', async () => {
    const studio = await setup('history');
    const r = studio.ctx.semilogResult;
    expect(studio.ctx.history).not.toBeNull();
    expect(r.method).toBe('superposition');
    expect(Math.abs(r.k / TRUTH.k - 1)).toBeLessThan(0.005);
    expect(Math.abs(r.skin - TRUTH.skin)).toBeLessThan(0.06);
    expect(Math.abs(r.pStar - resNum.pi)).toBeLessThan(0.05);
    expect(studio.ctx.flowSummary.note).toMatch(/analysed on this rate history/);
    expect(studio.ctx.flowSummary.mismatch).toEqual([]);
    studio.unmount();
  }, 600000);

  test('on one rate for tp the same data reads differently, and says so', async () => {
    const studio = await setup('tp');
    const r = studio.ctx.semilogResult;
    expect(studio.ctx.history).toBeNull();
    expect(r.method).toBe('horner');
    // Horner on one rate misreads the clean-up: k and skin both off
    expect(Math.abs(r.k / TRUTH.k - 1)).toBeGreaterThan(0.015);
    expect(Math.abs(r.skin - TRUTH.skin)).toBeGreaterThan(0.1);
    expect(studio.ctx.limitsRows.find(([k]) => k === 'Time basis')[1]).toMatch(/Horner/);
    studio.unmount();
  }, 600000);

  test('the productivity index sent to Nodal uses the last rate of the history, not the test rate q', async () => {
    const studio = await setup('history');
    await studio.act((c) => c.setReservoirField('q', '999'));
    expect(studio.ctx.wtaRecord.productivity.q_stb_d).toBe(140);
    expect(studio.ctx.wtaRecord.permeability.method).toMatch(/Superposition straight line/);
    studio.unmount();
  }, 600000);

  test('the auto-fit on the rate history recovers k, skin and C', async () => {
    const studio = await setup('history');
    await studio.act((c) => { c.setMatchField('k', '100'); c.setMatchField('skin', '0'); c.setMatchField('C', '0.01'); });
    await studio.act((c) => c.runAutoFit());
    const p = studio.ctx.matchParams;
    expect(Math.abs(p.k / TRUTH.k - 1)).toBeLessThan(0.01);
    expect(Math.abs(p.skin - TRUTH.skin)).toBeLessThan(0.05);
    expect(Math.abs(p.C / TRUTH.C - 1)).toBeLessThan(0.02);
    studio.unmount();
  }, 600000);
});

describe('a sealing fault from two semilog lines', () => {
  test('the late line doubles and gives the distance', async () => {
    const studio = mountStudio();
    const L = 555;
    const fault = getModel('homogeneous-sealing-fault');
    const bu = evaluateBuildup({ model: fault, params: { k: 225, skin: 3, C: 0.0004, L }, reservoir: resNum, tp: 30000, dts: logspace(-1, 3.7, 120) });
    await studio.act((c) => {
      Object.entries(RES).forEach(([k, v]) => c.setReservoirField(k, v));
      c.setTestField('testType', 'buildup');
      c.setTestField('tp', '30000');
      c.setTestField('pwfShutIn', String(bu.pwfAtShutIn));
      c.setTestField('pointsPerDecade', '30');
      c.setGaugeRows(bu.map((p) => ({ t: p.dt, p: p.pws })));
      c.setWindowField('semilogMin', '0.2');
      c.setWindowField('semilogMax', '1.9');
      c.setWindowField('lateMin', '950');
      c.setWindowField('lateMax', '3600');
    });
    const f = studio.ctx.faultResult;
    expect(f.ok).toBe(true);
    expect(Math.abs(f.L / L - 1)).toBeLessThan(0.05);
    expect(f.ratio).toBeGreaterThan(1.9);
    expect(studio.ctx.mdhBuildupResult.k / 225).toBeCloseTo(1, 1);
    studio.unmount();
  }, 600000);
});
